-- incidents (history + live demo) - inserted in chronological order so that
-- the trigger-computed priority uses the correct failure history

-- co-reporters (duplicates merged into originals) - trigger raises affected_users

-- work orders

-- spare parts consumed by completed work orders (price at time of use)

-- maintenance records (total_cost is a GENERATED column)

-- rebuild a realistic status timeline from work order timestamps --------
DELETE FROM incident_status_history;
SELECT incident_id, NULL, 'OPEN', reported_by, reported_at FROM incidents;

SELECT incident_id, 'OPEN', 'DUPLICATE', 2, reported_at + interval '20 minutes'
  FROM incidents WHERE status = 'DUPLICATE';

SELECT w.incident_id, 'OPEN', 'ASSIGNED', w.assigned_by, w.assigned_at FROM work_orders w;

SELECT w.incident_id, 'ASSIGNED', 'IN_PROGRESS', w.technician_id, w.started_at
  FROM work_orders w WHERE w.started_at IS NOT NULL;

SELECT i.incident_id, 'IN_PROGRESS', 'ON_HOLD', w.technician_id, w.started_at + interval '2 hours'
  FROM incidents i JOIN work_orders w ON w.incident_id = i.incident_id WHERE i.status = 'ON_HOLD';

SELECT w.incident_id, 'IN_PROGRESS', 'RESOLVED', w.technician_id, w.completed_at
  FROM work_orders w WHERE w.status = 'COMPLETED';

SELECT i.incident_id, 'RESOLVED', 'CLOSED', i.reported_by,
       LEAST(now(), i.resolved_at + interval '1 day')
  FROM incidents i WHERE i.status = 'CLOSED';

-- asset maintenance dates follow the maintenance history
UPDATE assets a
   SET last_maintenance_date = m.last_done
  FROM (SELECT asset_id, MAX(performed_on) AS last_done FROM maintenance_records GROUP BY asset_id) m
 WHERE m.asset_id = a.asset_id
   AND m.last_done > COALESCE(a.last_maintenance_date, a.install_date);

-- clean up alerts/audit rows produced while loading history, keep live ones
DELETE FROM alerts WHERE incident_id < 157;
TRUNCATE audit_log;
SELECT 'LOW_STOCK', CASE WHEN quantity_in_stock = 0 THEN 'CRITICAL' ELSE 'WARNING' END,
       format('Low stock: %s (%s) has %s left, reorder level is %s', part_name, part_code, quantity_in_stock, reorder_level),
       'ADMIN', part_id
  FROM spare_parts WHERE quantity_in_stock <= reorder_level;

-- derived data
UPDATE assets SET risk_score = fn_asset_risk_score(asset_id);

-- keep SERIAL sequences in sync with explicitly inserted ids
SELECT setval(pg_get_serial_sequence('roles', 'role_id'), (SELECT MAX(role_id) FROM roles));
SELECT setval(pg_get_serial_sequence('users', 'user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('buildings', 'building_id'), (SELECT MAX(building_id) FROM buildings));
SELECT setval(pg_get_serial_sequence('rooms', 'room_id'), (SELECT MAX(room_id) FROM rooms));
SELECT setval(pg_get_serial_sequence('asset_categories', 'category_id'), (SELECT MAX(category_id) FROM asset_categories));
SELECT setval(pg_get_serial_sequence('assets', 'asset_id'), (SELECT MAX(asset_id) FROM assets));
SELECT setval(pg_get_serial_sequence('incidents', 'incident_id'), (SELECT MAX(incident_id) FROM incidents));
SELECT setval(pg_get_serial_sequence('work_orders', 'work_order_id'), (SELECT MAX(work_order_id) FROM work_orders));
SELECT setval(pg_get_serial_sequence('spare_parts', 'part_id'), (SELECT MAX(part_id) FROM spare_parts));

COMMIT;

