INSERT INTO incidents (incident_id, title, description, incident_type, reported_by, room_id, asset_id, category_id, severity, affected_users, status, reported_at, resolved_at, duplicate_of, feedback_rating) VALUES (1, 'Mic and speakers not working', 'Since yesterday evening, the microphones and speakers in the main auditorium are not working and the audience cannot hear the speaker. Classes are getting disturbed because of this.', 'REACTIVE', 14, 27, 24, 6, 4, 505, 'CLOSED', now() - interval '252938 minutes', now() - interval '252589 minutes', NULL, NULL);
INSERT INTO incidents (incident_id, title, description, incident_type, reported_by, room_id, asset_id, category_id, severity, affected_users, status, reported_at, resolved_at, duplicate_of, feedback_rating) VALUES (2, 'AC not cooling - Auditorium', 'Since this morning, the AC in the main auditorium has been running for hours but the room is not cooling at all. It feels like it is only working as a fan. We already informed the floor in-charge.', 'REACTIVE', 17, 27, 6, 1, 3, 55, 'CLOSED', now() - interval '251298 minutes', now() - interval '250605 minutes', NULL, 5);
